            tokens.add(text[len(q['prefix'])] if len(text)>len(q['prefix']) else 'END')
        answers.append(dict(count=len(witnesses),tokens=sorted(tokens),witness=witnesses[0] if witnesses else None))
    return dict(rules=rules,active=active,answers=answers)

def random_job(rng):
    nf=rng.randrange(1,4);slots=rng.randrange(1,4)
    fields=[dict(name='f'+str(f),type=rng.choice(TYPES),domain=sorted(rng.sample([0,1,2,10,11,100,1000000],rng.randint(1,3)))) for f in range(nf)]
    refs={t:[[s,f['name']] for s in range(slots) for f in fields if f['type']==t] for t in TYPES}
    types=[t for t in TYPES if refs[t]]
    def term(t):
        kind=rng.choice(['ref','const','sum','scale'] if t in TYPES[:3] else ['ref','const'])
        if kind=='ref':return {'ref':rng.choice(refs[t])}
        if kind=='const':return {'const':rng.choice([0,1,2,5,10,11,999999,1000000]),'type':t}
        if kind=='sum':return {'sum':rng.sample(refs[t],rng.randint(1,min(len(refs[t]),slots)))}
        return {'ref':rng.choice(refs[t]),'scale':rng.choice([0,1,2,3,65535])}
    ps=[]
    for _ in range(rng.randrange(0,13)):
        if rng.randrange(3)==0:
            f=rng.choice(fields)
            ps.append(dict(kind=rng.choice(['any','all']),field=f['name'],op=rng.choice(list(OPS) if f['type'] in TYPES[:3] else ['eq','ne']),value=rng.choice([0,1,2,10,15,1000000])))
        else:
            t=rng.choice(types)
            ps.append(dict(kind='cmp',left=term(t),right=term(t),op=rng.choice(list(OPS) if t in TYPES[:3] else ['eq','ne'])))
        if rng.randrange(10)==0:ps[-1]=rng.choice(ps)
    width=rng.randint(1,4)
    train=[[[rng.choice(f['domain']) for f in fields] for s in range(slots)] for _ in range(rng.randint(1,15))]
    approved=[]
    for k in range(1,width+1):
        approved.extend(list(c) for c in itertools.combinations(range(len(ps)),k) if rng.randrange(3)==0)
    rng.shuffle(approved);approved=approved[:256]
    queries=[]
    for _ in range(10):
        target=[rng.randrange(slots),rng.choice(fields)['name']]
        fixed=[{'ref':[s,f['name']],'value':rng.choice(f['domain'])} for s in range(slots) for f in fields if [s,f['name']]!=target and rng.randrange(3)==0]
        rng.shuffle(fixed)
        queries.append(dict(fixed=fixed,target=target,prefix=rng.choice(['','0','00','01','1','10','11','2','9','1000000','1000001'])))
    return dict(fields=fields,slots=slots,predicates=ps,width=width,train=train,approved=approved,queries=queries)

